// Suporta tanto { "clientes": [...] } quanto um array direto [...] ou item único
const payload = $input.first().json;
const body = payload.body ? payload.body : payload;

let listaClientes = [];
if (Array.isArray(body.clientes)) {
  listaClientes = body.clientes;
} else if (Array.isArray(body)) {
  listaClientes = body;
} else {
  listaClientes = [body];
}

return listaClientes.map(cliente => {
  const perfilBruto = cliente.perfil || cliente.Perfil || "";
  return {
    json: {
      nome: cliente.nome || cliente.Nome || "Cliente",
      email: cliente.email || cliente.Email || "",
      saldo: cliente.saldo || cliente.Saldo || "0",
      perfil: perfilBruto,
      perfil_chave: perfilBruto.toString().trim().toLowerCase()
    }
  };
});

// Normaliza a coluna de perfil do CSV para garantir o cruzamento exato no Merge
return $input.all().map(item => {
  const row = item.json;
  const perfilCsv = row.perfil || row.Perfil || Object.values(row)[0] || "";
  return {
    json: {
      ...row,
      perfil_chave: perfilCsv.toString().trim().toLowerCase()
    }
  };
});

const item = $input.item.json;
const perfil = (item.perfil_chave || "").toLowerCase();

let estrategia = "";
switch (perfil) {
  case "conservador":
    estrategia = "Foco em renda fixa, liquidez e preservação de patrimônio com alta segurança.";
    break;
  case "moderado":
    estrategia = "Mix equilibrado entre a segurança da renda fixa e o potencial da renda variável.";
    break;
  case "arrojado":
    estrategia = "Ênfase em ações, fundos multimercado e maior potencial de retorno no longo prazo.";
    break;
  default:
    estrategia = "Diversificação inteligente alinhada aos seus objetivos financeiros.";
}

const opcaoRecomendada = item.produto || item.investimento || item.opcoes || item.recomendacao || item.ativo || "Carteira Recomendada por Perfil";

const mensagemMvp = `Olá, ${item.nome}! Com base no seu perfil ${item.perfil} e saldo disponível de R$ ${item.saldo}, nossa recomendação para você hoje é: ${opcaoRecomendada}. Diretriz da carteira: ${estrategia}`;

return {
  json: {
    ...item,
    opcao_recomendada: opcaoRecomendada,
    estrategia_base: estrategia,
    mensagem_mvp: mensagemMvp
  }
};

